update audit_operation_log
response_data = #{responseData}, status = #{status}, error_msg = #{errorMsg}, execution_time = #{executionTime}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where id = #{id}

mapper.select:
select count(*) as total_count, sum(case when status = 1 then 1 else 0 end) as success_count, sum(case when status = 0 then 1 else 0 end) as fail_count, sum(case when status = 1 then 1 else 0 end) / count(*) * 100 as success_rate, sum(execution_time) / count(*) as avg_execution_time from audit_operation_log
AND user_id = #{userId}
AND module = #{module}
AND date_format(operation_time,'%Y%m%d') >= date_format(#{beginTime},'%Y%m%d')
AND date_format(operation_time,'%Y%m%d') <= date_format(#{endTime},'%Y%m%d')
